 "content": "from collections import Counter


def transform(grid):
    """Extend matching colored bars on opposite edges inward as rays."""
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    def edge_runs(values):
        runs = []
        i = 0
        while i < len(values):
            color = values[i]
            j = i + 1
            while j < len(values) and values[j] == color:
                j += 1
            if color != bg and j - i >= 2:
                runs.append((color, i, j))
            i = j
        return runs

    # Find matching bars on opposite parallel edges (the bar color is distinct
    # from the sparse marker color used to draw the rays).
    bars = []
    for row, edge_name in ((0, "top"), (h - 1, "bottom")):
        for color, start, end in edge_runs(src[row]):
            bars.append(("h", edge_name, color, start, end))
    for col, edge_name in ((0, "left"), (w - 1, "right")):
        vals = [src[r][col] for r in range(h)]
        for color, start, end in edge_runs(vals):
            bars.append(("v", edge_name, color, start, end))

    # Locate opposite-edge pairs of bars with the same color.
    pairs = []
    for orient, a, color, start, end in bars:
        opposite = "bottom" if a == "top" else "top" if a == "bottom" else "right" if a == "left" else "left"
        for orient2, b, color2, start2, end2 in bars:
            if orient == orient2 and b == opposite and color2 == color:
                pairs.append((orient, a, color, start, end))
                break

    # The sparse non-background color(s) are the ray color. Bar cells are not
    # changed; rays stop at the first pre-existing object, marking a hit as 4.
    bar_colors = {p[2] for p in pairs}
    markers = {v for row in src for v in row if v != bg and v not in bar_colors}
    ray_color = next(iter(markers), 4)
    for orient, edge, color, start, end in pairs:
        if orient == "h":
            for c in range(start, end):
                if edge == "top":
                    rr = range(1, h)
                else:
                    rr = range(h - 2, -1, -1)
                for r in rr:
                    if src[r][c] != bg:
                        if src[r][c] == ray_color:
                            out[r][c] = 4
                        break
                    out[r][c] = ray_color
        else:
            for r in range(start, end):
                if edge == "left":
                    cc = range(1, w)
                else:
                    cc = range(w - 2, -1, -1)
                for c in cc:
                    if src[r][c] != bg:
                        if src[r][c] == ray_color:
                            out[r][c] = 4
                        break
                    out[r][c] = ray_color
    return out


if __name__ == "__main__":
    # Smoke-checks are driven externally with the supplied demonstration grids.
