def transform(grid):
    """Project each multi-cell colored edge bar inward as a ray."""
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    bars = []  # (orientation, edge, start, end, color), end exclusive

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                result.append((i, j, values[i]))
            i = j
        return result

    for edge, r in (("top", 0), ("bottom", h - 1)):
        for a, b, color in runs(src[r]):
            bars.append(("h", edge, a, b, color))
    for edge, c in (("left", 0), ("right", w - 1)):
        for a, b, color in runs([src[r][c] for r in range(h)]):
            bars.append(("v", edge, a, b, color))

    bar_cells = set()
    bar_colors = set()
    for orient, edge, a, b, color in bars:
        bar_colors.add(color)
        for i in range(a, b):
            bar_cells.add((0, i) if orient == "h" and edge == "top" else
                          (h - 1, i) if orient == "h" else
                          (i, 0) if edge == "left" else (i, w - 1))
    marks = [v for r, row in enumerate(src) for c, v in enumerate(row)
             if v != bg and (r, c) not in bar_cells]
    ray_color = Counter(marks).most_common(1)[0][0] if marks else 4

    for orient, edge, a, b, _color in bars:
        for i in range(a, b):
            if orient == "h":
                r_iter = range(1, h) if edge == "top" else range(h - 2, -1, -1)
                for r in r_iter:
                    if src[r][i] != bg:
                        out[r][i] = 4
                        break
                    out[r][i] = ray_color
            else:
                c_iter = range(1, w) if edge == "left" else range(w - 2, -1, -1)
                for c in c_iter:
                    if src[i][c] != bg:
                        out[i][c] = 4
                        break
                    out[i][c] = ray_color
    return out


if __name__ == "__main__":
    pass
