        return found

    bars = []
    for edge, r in (("top", 0), ("bottom", h - 1)):
        bars.extend(("h", edge, a, b) for a, b in runs(src[r]))
    for edge, c in (("left", 0), ("right", w - 1)):
        bars.extend(("v", edge, a, b) for a, b in runs([src[r][c] for r in range(h)]))

