 "content": "from collections import Counter


def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                result.append((i, j, values[i]))
            i = j
        return result

    # Border bars extend as rectangular strips of their own color. Impacts
    # (other non-background cells intersected by a strip) turn color 4.
    bars = []
    for edge, r in (("top", 0), ("bottom", h - 1)):
        bars.extend(("h", edge, a, b, color) for a, b, color in runs(src[r]))
    for edge, c in (("left", 0), ("right", w - 1)):
        bars.extend(("v", edge, a, b, color)
                    for a, b, color in runs([src[r][c] for r in range(h)]))

    impacts = set()
    for orient, edge, a, b, color in bars:
        if orient == "h":
            rows = range(1, h) if edge == "top" else range(h - 2, -1, -1)
            for r in rows:
                for c in range(a, b):
                    if src[r][c] != bg and src[r][c] != color:
                        impacts.add((r, c))
                    else:
                        out[r][c] = color
        else:
            cols = range(1, w) if edge == "left" else range(w - 2, -1, -1)
            for c in cols:
                for r in range(a, b):
                    if src[r][c] != bg and src[r][c] != color:
                        impacts.add((r, c))
                    else:
                        out[r][c] = color

    for r, c in impacts:
        out[r][c] = 4

    # Restore border source bars.
    for orient, edge, a, b, color in bars:
        for i in range(a, b):
            if orient == "h":
                r = 0 if edge == "top" else h - 1
                out[r][i] = src[r][i]
            else:
                c = 0 if edge == "left" else w - 1
                out[i][c] = src[i][c]
    return out


