 "content": "from collections import Counter


def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    background = Counter(v for row in src for v in row).most_common(1)[0][0]

    def edge_runs(row):
        result = []
        i = 0
        while i < len(row):
            j = i + 1
            while j < len(row) and row[j] == row[i]:
                j += 1
            if row[i] != background and j - i >= 2:
                result.append((i, j, row[i]))
            i = j
        return result

    bars = []
    for edge, r in (("top", 0), ("bottom", h - 1)):
        for a, b, color in edge_runs(src[r]):
            bars.append((edge, r, a, b, color))

    bar_cells = {(r, c) for _, r, a, b, _ in bars for c in range(a, b)}
    points = [(r, c) for r in range(h) for c in range(w)
              if src[r][c] != background and (r, c) not in bar_cells]
    point_color = Counter(src[r][c] for r, c in points).most_common(1)[0][0] if points else 4

    # Isolated marks are impacts. Each bar projects inward through its
    # right-hand half; a projected ray stops at its first non-background cell.
    for r, c in points:
        out[r][c] = 4

    for edge, source_r, a, b, _ in bars:
        beam_width = max(1, (b - a) // 2)
        beam_columns = range(b - beam_width, b)
        rows = range(source_r + 1, h - 1) if edge == "top" else range(source_r - 1, 0, -1)
        for c in beam_columns:
            for r in rows:
                if src[r][c] != background:
                    out[r][c] = 4
                    break
                out[r][c] = point_color

    return out


