 "content": "from collections import Counter


def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    # Find the long monochrome segments on all four grid edges.
    bars = []
    for edge, values in (("top", src[0]), ("bottom", src[-1]),
                         ("left", [src[r][0] for r in range(h)]),
                         ("right", [src[r][-1] for r in range(h)])):
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                bars.append((edge, i, j, values[i]))
            i = j

    bar_cells = set()
    for edge, a, b, _ in bars:
        for i in range(a, b):
            if edge == "top": bar_cells.add((0, i))
            elif edge == "bottom": bar_cells.add((h-1, i))
            elif edge == "left": bar_cells.add((i, 0))
            else: bar_cells.add((i, w-1))

    markers = [(r, c) for r in range(h) for c in range(w)
               if src[r][c] != bg and (r, c) not in bar_cells]
    mark_color = Counter(src[r][c] for r, c in markers).most_common(1)[0][0] if markers else 4

    # Horizontal edge bars project vertically; vertical bars project horizontally.
    for edge, a, b, color in bars:
        if edge in ("top", "bottom"):
            rows = range(1, h-1)
            for c in range(a, b):
                for r in rows:
                    if src[r][c] != bg and (r, c) not in bar_cells:
                        out[r][c] = 4
                    else:
                        out[r][c] = mark_color
