def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    # Find each multi-cell monochrome run on any border.
    bars = []
    for edge, values in (("top", src[0]), ("bottom", src[-1]),
                         ("left", [src[r][0] for r in range(h)]),
                         ("right", [src[r][-1] for r in range(h)])):
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                bars.append((edge, i, j, values[i]))
            i = j

    bar_cells = set()
    for edge, a, b, color in bars:
        for k in range(a, b):
            if edge == "top": bar_cells.add((0, k))
            elif edge == "bottom": bar_cells.add((h - 1, k))
            elif edge == "left": bar_cells.add((k, 0))
            else: bar_cells.add((k, w - 1))

    marks = [(r, c, src[r][c]) for r in range(h) for c in range(w)
             if src[r][c] != bg and (r, c) not in bar_cells]
    mark_color = Counter(v for _, _, v in marks).most_common(1)[0][0] if marks else 4

    # A border run grows inward as a rectangle one run-width deep. Marks hit
    # inside the rectangle become 4; other cells take the mark color.
    for edge, a, b, _ in bars:
        length = b - a
        if edge == "top":
            rows = range(1, min(h - 1, length + 1))
            cols = range(max(0, a - length), min(w, b + length))
        elif edge == "bottom":
            rows = range(max(1, h - 1 - length), h - 1)
            cols = range(max(0, a - length), min(w, b + length))
        elif edge == "left":
            rows = range(max(0, a - length), min(h, b + length))
            cols = range(1, min(w - 1, length + 1))
        else:
            rows = range(max(0, a - length), min(h, b + length))
            cols = range(max(1, w - 1 - length), w - 1)
        for r in rows:
            for c in cols:
                out[r][c] = 4 if any(r == mr and c == mc for mr, mc, _ in marks) else mark_color

    # Preserve all original border runs.
    for r, c in bar_cells:
        out[r][c] = src[r][c]
    return out


