def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    def runs(values):
        ans = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                ans.append((i, j, values[i]))
            i = j
        return ans

    bars = []
    for edge, row in (("top", src[0]), ("bottom", src[-1])):
        for a, b, color in runs(row):
            bars.append((edge, a, b, color))
    border = {(0 if edge == "top" else h - 1, c)
              for edge, a, b, _ in bars for c in range(a, b)}
    markers = [(r, c) for r in range(h) for c in range(w)
               if src[r][c] != bg and (r, c) not in border]
    marker_color = Counter(src[r][c] for r, c in markers).most_common(1)[0][0] if markers else 4

    # Each marker projects a ray toward the nearest edge bar along its row or
    # column, preserving the marker color along the path and marking the source 4.
    for r, c in markers:
        choices = []
        for edge, a, b, _ in bars:
            if edge in ("top", "bottom") and a <= c < b:
                er = 0 if edge == "top" else h - 1
                choices.append((abs(r - er), "v", er))
        if choices:
            _, axis, target = min(choices)
            out[r][c] = 4
            step = 1 if target > r else -1
            rr = r + step
            while rr != target:
                out[rr][c] = marker_color
                rr += step
    return out


