                j += 1
            if values[i] != bg and j - i >= 2:
                result.append((i, j, values[i]))
            i = j
        return result

    bars = []
    for edge, values in (("top", src[0]), ("bottom", src[-1]),
                         ("left", [src[r][0] for r in range(h)]),
                         ("right", [src[r][-1] for r in range(h)])):
        bars.extend((edge, a, b, color) for a, b, color in runs(values))

    border = set()
    for edge, a, b, _ in bars:
        for i in range(a, b):
            if edge == "top": border.add((0, i))
            elif edge == "bottom": border.add((h - 1, i))
            elif edge == "left": border.add((i, 0))
            else: border.add((i, w - 1))

    markers = [(r, c, src[r][c]) for r in range(h) for c in range(w)
               if src[r][c] != bg and (r, c) not in border]

    # Markers project toward a matching edge bar along their row or column.
    # The path is filled in the marker's color, the marker becomes 4, and
    # the edge bar itself remains unchanged.
    for r, c, color in markers:
        options = []
        for edge, a, b, _ in bars:
            if edge in ("top", "bottom") and a <= c < b:
                target_r = 0 if edge == "top" else h - 1
                options.append((abs(r - target_r), "vertical", target_r))
            elif edge in ("left", "right") and a <= r < b:
                target_c = 0 if edge == "left" else w - 1
                options.append((abs(c - target_c), "horizontal", target_c))
        if not options:
            continue
        _, direction, target = min(options)
        out[r][c] = 4
        if direction == "vertical":
            step = 1 if target > r else -1
            rr = r + step
            while rr != target:
                out[rr][c] = color
                rr += step
        else:
            step = 1 if target > c else -1
            cc = c + step
            while cc != target:
