def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                result.append((i, j, values[i]))
            i = j
        return result

    bars = []
    for edge, values in (("top", src[0]), ("bottom", src[-1]),
                         ("left", [src[r][0] for r in range(h)]),
                         ("right", [src[r][-1] for r in range(h)])):
        bars.extend((edge, a, b, color) for a, b, color in runs(values))

    border = set()
    for edge, a, b, _ in bars:
        for k in range(a, b):
            if edge == "top":
                border.add((0, k))
            elif edge == "bottom":
                border.add((h - 1, k))
            elif edge == "left":
                border.add((k, 0))
            else:
                border.add((k, w - 1))

    markers = [(r, c, src[r][c]) for r in range(h) for c in range(w)
               if src[r][c] != bg and (r, c) not in border]

    # Opposing edge bars pair positions by offset along their length. A marker
    # projects toward its supporting edge; the paired position on the opposite
    # bar projects a full line across the interior.
    for r, c, color in markers:
        aligned = []
        for edge, a, b, _ in bars:
            if edge in ("top", "bottom") and a <= c < b:
                distance = r if edge == "top" else h - 1 - r
                aligned.append((distance, edge, a, b, c - a))
            elif edge in ("left", "right") and a <= r < b:
                distance = c if edge == "left" else w - 1 - c
                aligned.append((distance, edge, a, b, r - a))
        if not aligned:
            continue
        _, edge, a, b, offset = min(aligned)
        out[r][c] = 4

        # Fill from the marker toward its supporting edge.
        if edge == "top":
            for rr in range(r - 1, 0, -1):
                out[rr][c] = color
            opposite = "bottom"
        elif edge == "bottom":
            for rr in range(r + 1, h - 1):
                out[rr][c] = color
            opposite = "top"
        elif edge == "left":
            for cc in range(c - 1, 0, -1):
                out[r][cc] = color
            opposite = "right"
        else:
            for cc in range(c + 1, w - 1):
                out[r][cc] = color
            opposite = "left"

        paired = [bar for bar in bars if bar[0] == opposite]
        if not paired:
            continue
        other = min(paired, key=lambda bar: abs((bar[2] - bar[1]) - (b - a)))
        paired_pos = other[1] + offset
        if opposite in ("top", "bottom"):
            for rr in range(1, h - 1):
                out[rr][paired_pos] = color
        else:
            for cc in range(1, w - 1):
                out[paired_pos][cc] = color

    return out


