def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    bg = Counter(v for row in src for v in row).most_common(1)[0][0]

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                result.append((i, j, values[i]))
            i = j
        return result

    # Opposing bars frame a set of matching projection lanes.
    for axis in ("horizontal", "vertical"):
        if axis == "horizontal":
            first = [(a, b, color) for a, b, color in runs(src[0])]
            second = [(a, b, color) for a, b, color in runs(src[-1])]
        else:
            first = [(a, b, color) for a, b, color in runs([src[r][0] for r in range(h)])]
            second = [(a, b, color) for a, b, color in runs([src[r][-1] for r in range(h)])]

        for a1, b1, bar_color in first:
            for a2, b2, _ in second:
                if b1 - a1 != b2 - a2:
                    continue
                length = b1 - a1
                if axis == "horizontal":
                    markers = [(r, c, src[r][c]) for r in range(1, h - 1)
                               for c in range(w) if src[r][c] != bg and a1 <= c < b1]
                    for r, c, marker_color in markers:
                        offset = c - a1
                        c_top, c_bottom = a1 + offset, a2 + offset
                        # Fire from each bar toward the opposite edge. A hit is
                        # recolored 4, and that ray stops at the hit.
                        for start_r, step, col in ((0, 1, c_top), (h - 1, -1, c_bottom)):
                            rr = start_r + step
                            while 0 < rr < h - 1:
                                if src[rr][col] != bg:
                                    out[rr][col] = 4
                                    break
                                out[rr][col] = marker_color
                                rr += step
                        out[r][c] = 4
                else:
                    markers = [(r, c, src[r][c]) for r in range(h)
                               for c in range(1, w - 1) if src[r][c] != bg and a1 <= r < b1]
                    for r, c, marker_color in markers:
                        offset = r - a1
                        r_left, r_right = a1 + offset, a2 + offset
